<?php
require_once '../db.php';
session_start();
$ket_noi->exec("CREATE TABLE IF NOT EXISTS security_lab_comments (id INT AUTO_INCREMENT PRIMARY KEY, content TEXT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP)");
$mode=$_GET['mode']??'vulnerable'; $msg=$_GET['msg']??'';
if($_SERVER['REQUEST_METHOD']==='POST' && isset($_POST['comment'])){ $comment=$_POST['comment']; $st=$ket_noi->prepare('INSERT INTO security_lab_comments(content) VALUES (?)'); $st->execute([$comment]); header('Location:xss.php?mode='.$mode); exit; }
$comments=$ket_noi->query('SELECT content,created_at FROM security_lab_comments ORDER BY id DESC LIMIT 10')->fetchAll(PDO::FETCH_ASSOC);
?><!doctype html><html lang="vi"><head><meta charset="utf-8"><title>XSS Lab</title></head><body style="font-family:Arial;max-width:900px;margin:30px auto"><h1>XSS Lab</h1><h2>Reflected</h2><form><input name="msg" value="<?=htmlspecialchars($msg,ENT_QUOTES,'UTF-8')?>"><select name="mode"><option value="vulnerable" <?= $mode==='vulnerable'?'selected':'' ?>>vulnerable</option><option value="fixed" <?= $mode==='fixed'?'selected':'' ?>>fixed</option></select><button>Test</button></form><div style="padding:12px;border:1px solid #ccc;margin-top:10px"><?php if($mode==='vulnerable') echo $msg; else echo htmlspecialchars($msg,ENT_QUOTES,'UTF-8'); ?></div><h2>Stored</h2><form method="post"><textarea name="comment" rows="4" cols="70" placeholder="Lab comment"></textarea><br><button>Save</button></form><ul><?php foreach($comments as $c): ?><li><?php echo $mode==='vulnerable' ? $c['content'] : htmlspecialchars($c['content'],ENT_QUOTES,'UTF-8'); ?> <small>(<?=$c['created_at']?>)</small></li><?php endforeach; ?></ul><p><b>Fixed principle:</b> encode output according to HTML context; validate input; add CSP.</p><p><a href="index.php">← Lab menu</a></p></body></html>